function compose(){return heading('Um link. Sua próxima publicação.','Cole um link do Mercado Livre ou da Shopee e prepare um post para sua revisão.','CRIAR POST POR LINK')+`<div class="composer-grid"><section class="search-panel"><h2>Comece pelo seu achado</h2><p class="subtitle">Complete os dados confirmados na loja. O link identifica a loja; título e preço não são extraídos automaticamente.</p><form id="compose-form"><label>Link do produto ou seu link de afiliado<input id="compose-url" name="url" type="url" required placeholder="https://…"></label><p id="compose-store-hint" class="form-note">Aceitamos links do Mercado Livre e da Shopee, inclusive links curtos dessas lojas.</p><label class="check-label"><input name="isAffiliate" id="compose-affiliate" type="checkbox">Este já é o meu link de afiliado</label><label>Nome do produto<input name="title" required maxlength="160" placeholder="Ex.: Nécessaire de viagem com gancho"></label><div class="form-grid"><label>Categoria<select name="category"><option>Casa</option><option>Beleza</option></select></label><label>Preço confirmado (R$)<input name="price" type="number" min="0.01" step="0.01" required placeholder="29,90"></label></div><label>Cupom confirmado <span class="optional">opcional</span><input name="coupon" maxlength="60" placeholder="Somente se você conferiu as condições"></label><label>Condições ou observações<textarea name="notes" rows="2" maxlength="1000" placeholder="Variação, forma de pagamento, frete…"></textarea></label><button class="button primary" type="submit">Montar texto ↗</button></form></section><section class="search-panel composer-preview"><p class="eyebrow">PRÉVIA DA MENSAGEM</p><h2>Seu post começa aqui.</h2><p class="subtitle">A mensagem usa os dados que você informou. Você pode editar o texto antes de salvar.</p><label for="compose-message">Mensagem para revisão</label><textarea id="compose-message" rows="13" class="review-message" placeholder="Cole um link e preencha os detalhes para montar sua mensagem." disabled></textarea><div class="notice">Nada é enviado automaticamente. A aprovação continua obrigatória; links comuns precisam ser substituídos pelo seu link de afiliado antes de aprovar.</div><button class="button primary" id="compose-save" disabled>Salvar para revisão</button><p id="compose-feedback" class="form-note" role="status"></p></section></div><section class="notice schedule-summary"><strong>Busca programada · 4 vezes ao dia</strong><br>8h, 12h, 16h e 20h · horário de Brasília. A automação roda pelo Codex nesta conversa e precisa deste computador ligado e com o aplicativo aberto. A plataforma não executa buscas por conta própria.</section>`}
function identifyStore(value){const url=safeURL(value);if(!url)return null;const host=new URL(url).hostname;const match=domain=>host===domain||host.endsWith('.'+domain);if(['mercadolivre.com.br','mercadolibre.com','meli.la'].some(match))return 'Mercado Livre';if(['shopee.com.br','shope.ee'].some(match))return 'Shopee';return null}
function bindComposer(){const f=$('#compose-form');let candidate=null;
 const invalidate=()=>{candidate=null;$('#compose-save').disabled=true;$('#compose-feedback').textContent='';if(!$('#compose-message').disabled)$('#compose-feedback').textContent='Os dados mudaram. Monte o texto novamente antes de salvar.'};
 f.addEventListener('input',()=>{invalidate();const store=identifyStore(f.elements.url.value);$('#compose-store-hint').textContent=store?'Loja identificada: '+store+'. Confira os dados do anúncio.':'Cole um link HTTPS válido do Mercado Livre ou da Shopee.'});
 f.addEventListener('change',invalidate);
 f.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));const store=identifyStore(v.url);if(!store){toast('Use um link HTTPS do Mercado Livre ou da Shopee.');return}const price=Number(v.price);if(!v.title.trim()||!Number.isFinite(price)||price<=0){toast('Informe o nome do produto e um preço válido.');return}candidate={id:crypto.randomUUID(),title:v.title.trim(),category:v.category,store,price,oldPrice:null,url:safeURL(v.url),affiliate:$('#compose-affiliate').checked?safeURL(v.url):'',coupon:v.coupon.trim(),notes:v.notes.trim(),text:'',stage:$('#compose-affiliate').checked?'draft':'found',demo:false,createdAt:new Date().toISOString()};const draft=makeText({...candidate,affiliate:candidate.affiliate||candidate.url});$('#compose-message').disabled=false;$('#compose-message').value=draft;$('#compose-save').disabled=false;$('#compose-feedback').textContent=candidate.affiliate?'Edite a mensagem e salve para revisar e aprovar.':'Você pode salvar o achado. Adicione seu link de afiliado para liberar a aprovação.'};
 $('#compose-save').onclick=()=>{if(!candidate)return;const text=$('#compose-message').value.trim();if(!text){toast('Escreva uma mensagem para salvar.');return}const item={...candidate,text};if(!validate(item)){toast('Confira os dados antes de salvar.');return}if(offers.some(o=>o.url===item.url&&!o.demo)){if(!confirm('Este link já existe no painel. Criar um novo rascunho mesmo assim?'))return}offers.unshift(item);persist();go('flow');if(item.affiliate)review(item.id);toast(item.affiliate?'Post salvo para revisão. Confira e aprove a mensagem.':'Achado salvo. Adicione seu link de afiliado para continuar.')};
}
